/**
 * The RiSips logo as plain data, from the brand sheet (brand/ at the repo root).
 *
 * The mark is a 28-unit band on a 166-unit grid that turns four times, folds
 * inward and stops; the point sits in the corner it left open. It is drawn as a
 * solid shape, the way the sheet draws it: softened outer corners, sharp inner
 * corners, round ends. Scale the vector; never redraw it.
 *
 * The wordmark's i-dots are their own path so they can take the point's colour.
 * Generated by one script for every app, so the three copies cannot drift.
 */

export const LogoColors = {
  /** The mark and the letters, on paper. */
  blue: '#0160C2',
  /** The point and the i-dots, on paper and on blue alike. */
  yellow: '#F2B84B',
} as const;

